using System;using System.Linq;using UnityEngine;using UnityEditor;using AntColony.Units;
public static class Native1112Bindings{public static string Run(){if(Application.isPlaying)throw new Exception("Edit required");var lib=Resources.Load<MeshyNativeLibrary>("MeshyNative/Library");lib.actions=AntColony.EditorTools.MeshyNativeActionBindings.All().Select(p=>new MeshyNativeLibrary.ActionBinding{action=p.Key,motion=p.Value}).ToArray();foreach(var a in lib.actions)if(!lib.motions.Any(m=>m.id==a.motion))throw new Exception(a.motion);var runtime=Resources.Load<MeshyNativeLibrary>("MeshyNative/Runtime");runtime.actions=lib.actions;runtime.motions=lib.motions.Where(m=>lib.actions.Any(a=>a.motion==m.id)).ToArray();EditorUtility.SetDirty(lib);EditorUtility.SetDirty(runtime);AssetDatabase.SaveAssets();return runtime.actions.Length+" actions / "+runtime.motions.Length+" original source clips";}}
